/// Settings for systematic choices. `Kashubian::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Kashubian {
    pub options: Options,
}

impl Kashubian {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Genitive, Number::Singular,) => Some(2),
            (Case::Genitive, Number::Plural,) => Some(3),
            (Case::Dative, Number::Singular,) => Some(4),
            (Case::Dative, Number::Plural,) => Some(5),
            (Case::Accusative, Number::Singular,) => Some(6),
            (Case::Accusative, Number::Plural,) => Some(7),
            (Case::Instrumental, Number::Singular,) => Some(8),
            (Case::Instrumental, Number::Plural,) => Some(9),
            (Case::Locative, Number::Singular,) => Some(10),
            (Case::Locative, Number::Plural,) => Some(11),
            (Case::Vocative, Number::Singular,) => Some(12),
            (Case::Vocative, Number::Plural,) => Some(13),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_scored(word, case, number), word)
    }

    /// The diminutive noun.
    pub fn noun_diminutive_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(14);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The diminutive noun. The best candidate; the word itself if nothing is known.
    pub fn noun_diminutive(&self, word: &str) -> String {
        best(self.noun_diminutive_scored(word), word)
    }

    /// The augmentative noun.
    pub fn noun_augmentative_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(15);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The augmentative noun. The best candidate; the word itself if nothing is known.
    pub fn noun_augmentative(&self, word: &str) -> String {
        best(self.noun_augmentative_scored(word), word)
    }

    /// Scored gender of a noun.
    pub fn noun_gender(&self, word: &str) -> Scored<Gender> {
        model().map(|m| m.inherent(0, 0, word).into_iter().filter_map(|(v, p)| Some((Gender::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Scored animacy of a noun.
    pub fn noun_animacy(&self, word: &str) -> Scored<Animacy> {
        model().map(|m| m.inherent(0, 1, word).into_iter().filter_map(|(v, p)| Some((Animacy::ALL.get(v as usize).copied()?, p))).collect()).unwrap_or_default()
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// A adj form.
    pub fn adj_scored(&self, word: &str, case: Case, singular_gender: SingularGender) -> Scored<String> {
        let cell: Option<u32> = match (case, singular_gender,) {
            (Case::Nominative, SingularGender::Masculine,) => Some(0),
            (Case::Nominative, SingularGender::MasculineAnimate,) => Some(1),
            (Case::Nominative, SingularGender::Neuter,) => Some(2),
            (Case::Nominative, SingularGender::Feminine,) => Some(3),
            (Case::Genitive, SingularGender::Masculine,) => Some(4),
            (Case::Genitive, SingularGender::MasculineAnimate,) => Some(5),
            (Case::Genitive, SingularGender::Neuter,) => Some(6),
            (Case::Genitive, SingularGender::Feminine,) => Some(7),
            (Case::Dative, SingularGender::Masculine,) => Some(8),
            (Case::Dative, SingularGender::MasculineAnimate,) => Some(9),
            (Case::Dative, SingularGender::Neuter,) => Some(10),
            (Case::Dative, SingularGender::Feminine,) => Some(11),
            (Case::Accusative, SingularGender::Masculine,) => Some(12),
            (Case::Accusative, SingularGender::MasculineAnimate,) => Some(13),
            (Case::Accusative, SingularGender::Neuter,) => Some(14),
            (Case::Accusative, SingularGender::Feminine,) => Some(15),
            (Case::Instrumental, SingularGender::Masculine,) => Some(16),
            (Case::Instrumental, SingularGender::MasculineAnimate,) => Some(17),
            (Case::Instrumental, SingularGender::Neuter,) => Some(18),
            (Case::Instrumental, SingularGender::Feminine,) => Some(19),
            (Case::Locative, SingularGender::Masculine,) => Some(20),
            (Case::Locative, SingularGender::MasculineAnimate,) => Some(21),
            (Case::Locative, SingularGender::Neuter,) => Some(22),
            (Case::Locative, SingularGender::Feminine,) => Some(23),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form. The best candidate; the word itself if nothing is known.
    pub fn adj(&self, word: &str, case: Case, singular_gender: SingularGender) -> String {
        best(self.adj_scored(word, case, singular_gender), word)
    }

    /// A adj form (plural).
    pub fn adj_plural_scored(&self, word: &str, case: Case, virility: Virility) -> Scored<String> {
        let cell: Option<u32> = match (case, virility,) {
            (Case::Nominative, Virility::Virile,) => Some(24),
            (Case::Nominative, Virility::Nonvirile,) => Some(25),
            (Case::Genitive, Virility::Virile,) => Some(26),
            (Case::Genitive, Virility::Nonvirile,) => Some(27),
            (Case::Dative, Virility::Virile,) => Some(28),
            (Case::Dative, Virility::Nonvirile,) => Some(29),
            (Case::Accusative, Virility::Virile,) => Some(30),
            (Case::Accusative, Virility::Nonvirile,) => Some(31),
            (Case::Instrumental, Virility::Virile,) => Some(32),
            (Case::Instrumental, Virility::Nonvirile,) => Some(33),
            (Case::Locative, Virility::Virile,) => Some(34),
            (Case::Locative, Virility::Nonvirile,) => Some(35),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form (plural). The best candidate; the word itself if nothing is known.
    pub fn adj_plural(&self, word: &str, case: Case, virility: Virility) -> String {
        best(self.adj_plural_scored(word, case, virility), word)
    }

    /// A adj form (simple).
    pub fn adj_simple_scored(&self, word: &str, degree: Degree) -> Scored<String> {
        let cell: Option<u32> = match (degree,) {
            (Degree::Comparative,) => Some(36),
            (Degree::Superlative,) => Some(37),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A adj form (simple). The best candidate; the word itself if nothing is known.
    pub fn adj_simple(&self, word: &str, degree: Degree) -> String {
        best(self.adj_simple_scored(word, degree), word)
    }

    /// Dictionary spelling of a adj (with stress marks where the data has them).
    pub fn adj_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

}

